def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: str representation of total seconds or None if invalid
    """
    if value is None:
        return None
    try:
        seconds = value.total_seconds()
    except Exception:
        return None
    if isinstance(seconds, float) and seconds.is_integer():
        return str(int(seconds))
    return str(seconds)<|return|>

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        return value.isoformat()
    except AttributeError:
        raise TypeError(f"Expected a datetime.time instance, got {type(value).__name__}")<|return|>

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        raise ValueError("value cannot be None")
    # Ensure required attributes exist
    try:
        lat = getattr(value, 'lat')
        lon = getattr(value, 'lon')
        time = getattr(value, 'time')
    except AttributeError as e:
        raise TypeError("value must have 'lat', 'lon', and 'time' attributes") from e
    # Convert lat/lon to float
    try:
        lat = float(lat)
        lon = float(lon)
    except (TypeError, ValueError) as e:
        raise ValueError("lat and lon must be numeric") from e
    # Convert time to ISO string if possible
    if time is None:
        time_str = None
    elif hasattr(time, 'isoformat') and callable(time.isoformat):
        try:
            time_str = time.isoformat()
        except Exception as e:
            raise ValueError("time attribute could not be converted to ISO format") from e
    else:
        time_str = time
    return {'lat': lat, 'lon': lon, 'time': time_str}<|return|>

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        if hasattr(self, "_keys") and self._keys is not None:
            if isinstance(self._keys, dict):
                return list(self._keys.keys())
            if isinstance(self._keys, list):
                return [k.name if hasattr(k, "name") else k for k in self._keys]
        return []
    except Exception:
        return []<|return|>

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError('Key not found: %s' % key)<|return|>

def values(self, *keys):
    """Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Determine the underlying items representation
    if hasattr(self, "_items"):
        items = self._items
    else:
        # Fallback to dict-like interface
        try:
            items = list(self.items())
        except AttributeError:
            raise TypeError("Object does not provide items for value extraction")

    # Build a list of values in order
    values_list = [v for _, v in items]

    # If no keys specified, return all values
    if not keys:
        return values_list

    # Collect requested values
    result = []
    for key in keys:
        if isinstance(key, int):
            # Index-based access
            try:
                result.append(values_list[key])
            except IndexError as exc:
                raise IndexError(f"Index {key} out of range for values list") from exc
        else:
            # Key-based access
            for k, v in items:
                if k == key:
                    result.append(v)
                    break
            else:
                raise KeyError(f"Key {key!r} not found in record")
    return result<|return|>

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    # Validate input
    try:
        from collections.abc import Sequence as _Sequence
    except Exception:
        _Sequence = tuple  # Fallback if collections.abc is unavailable
    if seq is None:
        raise TypeError("seq must not be None")
    if not isinstance(seq, _Sequence):
        raise TypeError("seq must be a sequence")
    if not all(isinstance(item, str) for item in seq):
        raise TypeError("all elements of seq must be strings")
    # Deterministic shuffle using a fixed seed
    import random as _random
    rng = _random.Random(0)
    shuffled = list(seq)
    try:
        rng.shuffle(shuffled)
    except Exception as exc:
        raise RuntimeError(f"Failed to shuffle sequence: {exc}") from exc
    return shuffled<|return|>

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return wrapper
    return decorator<|return|>

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not callable(timer):
        raise TypeError("timer must be callable")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    def decorator(func):
        cache = {}
        order = []

        def make_key(args, kwargs):
            key = args
            if kwargs:
                # sort keyword items to ensure deterministic order
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            if key in cache:
                value, expire = cache[key]
                if expire > now:
                    # Update LRU order
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
                    order.append(key)
                    return value
                else:
                    # Expired entry
                    del cache[key]
                    try:
                        order.remove(key)
                    except ValueError:
                        pass

            # Compute new value
            result = func(*args, **kwargs)
            expire = now + ttl
            cache[key] = (result, expire)
            order.append(key)

            # Evict least recently used if over capacity
            if len(cache) > maxsize:
                oldest = order.pop(0)
                cache.pop(oldest, None)

            return result

        return wrapper

    return decorator<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError('dictionary is empty')
    value = self.pop(key)
    return (key, value)<|return|>

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    try:
        if key in self._value:
            return self._value[key]
        self._value[key] = default
        return default
    except TypeError as exc:
        raise ValueError(f"Invalid key {key!r}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Error setting default for key {key!r}: {exc}") from exc<|return|>

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default<|return|>

