def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Validate the `all` argument
    if not isinstance(all, bool):
        raise TypeError(f"'all' must be a bool, got {type(all).__name__}")

    # Determine which attributes to inspect
    if all:
        # Inspect all attributes available on the instance (including inherited)
        attr_names = dir(self)
    else:
        # Inspect only attributes defined directly on the class
        attr_names = list(self.__class__.__dict__.keys())

    results = []

    for name in attr_names:
        # Skip private and special attributes
        if name.startswith("_"):
            continue
        # Skip built-in attributes that are not part of the interface
        if name in ("__class__", "__dict__", "__weakref__", "__module__", "__doc__"):
            continue

        try:
            attr = getattr(self, name)
        except Exception:
            # If accessing the attribute raises an exception, skip it
            continue

        # Skip callables (methods, functions, builtins)
        if callable(attr):
            continue

        description = ""

        # Handle property objects
        if isinstance(attr, property):
            fget = attr.fget
            if fget and fget.__doc__:
                description = fget.__doc__
        else:
            # For other objects, use their __doc__ if available
            if hasattr(attr, "__doc__") and attr.__doc__:
                description = attr.__doc__

        results.append((name, description))

    # Sort results by attribute name for consistency
    results.sort(key=lambda x: x[0])
    return results<|return|>

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("`all` must be a boolean value")

    attr_names = set()

    # Helper to collect names from a class dictionary
    def _collect_from_dict(cls_dict):
        for name, value in cls_dict.items():
            # Skip private/internal names and callables
            if name.startswith("_") or callable(value):
                continue
            attr_names.add(name)

    if all:
        # Include attributes from the class and all base classes
        for cls in self.__class__.__mro__:
            _collect_from_dict(cls.__dict__)
            # Include __slots__ if present
            slots = getattr(cls, "__slots__", ())
            if isinstance(slots, str):
                slots = (slots,)
            for slot_name in slots:
                if not slot_name.startswith("_"):
                    attr_names.add(slot_name)
    else:
        # Only attributes defined directly on the class
        _collect_from_dict(self.__class__.__dict__)
        slots = getattr(self.__class__, "__slots__", ())
        if isinstance(slots, str):
            slots = (slots,)
        for slot_name in slots:
            if not slot_name.startswith("_"):
                attr_names.add(slot_name)

    return sorted(attr_names)<|return|>

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If sequence is None, nothing to do
    if sequence is None:
        return output

    # Helper to determine if an object is iterable but not a string/bytes
    def _is_iterable(obj):
        return hasattr(obj, "__iter__") and not isinstance(obj, (str, bytes))

    # If the sequence is a tuple/list/set (or any iterable except string/bytes),
    # iterate over its elements and recurse
    if isinstance(sequence, (list, tuple, set)) or _is_iterable(sequence):
        try:
            for v in sequence:
                _normalizeargs(v, output)
        except Exception:
            # If iteration fails, treat the sequence as a single element
            output.append(sequence)
    # If the sequence is a class (type), treat it as an interface
    elif isinstance(sequence, type):
        output.append(sequence)
    else:
        # For any other object, treat it as a single interface
        output.append(sequence)

    return output<|return|>

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
