def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset context
    self.context = {}

    # Reinitialize bins
    try:
        # If an explicit initial value is provided, use it to fill bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Preserve the existing bin structure if present
            if hasattr(self, "bins") and self.bins is not None:
                bin_count = len(self.bins)
                self.bins = [self.initial_value] * bin_count
            else:
                # If no bins exist yet, create a single bin with the initial value
                self.bins = [self.initial_value]
        else:
            # Fall back to the make_bins method if available
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                raise AttributeError(
                    "Cannot reset bins: neither 'initial_value' nor 'make_bins' is defined."
                )
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc
<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input
    if not isinstance(coord_name, str):
        raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")
    if not hasattr(self, "_variables"):
        raise AttributeError("Instance has no attribute '_variables'")
    vars_obj = self._variables
    # Helper to find index in a dict or list
    def _find_index(name):
        if isinstance(vars_obj, dict):
            keys = list(vars_obj.keys())
            try:
                return keys.index(name)
            except ValueError:
                return None
        elif isinstance(vars_obj, (list, tuple)):
            for idx, item in enumerate(vars_obj):
                # If items are strings, compare directly
                if isinstance(item, str) and item == name:
                    return idx
                # If items are objects with a 'name' attribute
                if hasattr(item, "name") and item.name == name:
                    return idx
            return None
        else:
            raise TypeError(f"Unsupported type for _variables: {type(vars_obj).__name__}")

    # Common naming convention: <coord_name>_err
    err_name = f"{coord_name}_err"
    idx = _find_index(err_name)
    if idx is not None:
        return [idx]
    # Fallback: search for any key that starts with coord_name and ends with '_err'
    if isinstance(vars_obj, dict):
        for key in vars_obj:
            if key.startswith(coord_name) and key.endswith("_err"):
                return [list(vars_obj.keys()).index(key)]
    elif isinstance(vars_obj, (list, tuple)):
        for i, item in enumerate(vars_obj):
            name = item if isinstance(item, str) else getattr(item, "name", None)
            if name and name.startswith(coord_name) and name.endswith("_err"):
                return [i]
    # No error variable found
    return []<|return|>

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Reject Source sequences outright
    if isinstance(seq, Source):
        return False
    # Direct FillRequest instance is acceptable
    if isinstance(seq, FillRequest):
        return True
    # Non-iterable objects cannot be sequences
    try:
        iterator = iter(seq)
    except TypeError:
        return False
    # Strings and bytes are iterable but not considered sequences here
    if isinstance(seq, (str, bytes)):
        return False
    # Check for at least one FillRequest element
    for item in iterator:
        if isinstance(item, FillRequest):
            return True
    return False<|return|>

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        if obj is None:
            return False
        has_fill = hasattr(obj, 'fill') and callable(getattr(obj, 'fill', None))
        has_request = hasattr(obj, 'request') and callable(getattr(obj, 'request', None))
        return has_fill and has_request
    except Exception:
        return False<|return|>

def is_run_el(obj):
    """Object contains executable method 'run'."""
