def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Allow iterable coordinates (e.g., list or array) by delegating to scalar case
    if hasattr(coord, "__iter__") and not isinstance(coord, (str, bytes)):
        for c in coord:
            self.fill(c, weight)
        return

    # Validate numeric types
    try:
        coord_val = float(coord)
    except Exception as exc:
        raise TypeError("coord must be a numeric value") from exc
    try:
        weight_val = float(weight)
    except Exception as exc:
        raise TypeError("weight must be numeric") from exc

    # Ignore out-of-range coordinates
    if coord_val < self.edges[0] or coord_val > self.edges[-1]:
        return

    # Find the bin index (left-closed, right-open except last bin)
    idx = np.searchsorted(self.edges, coord_val, side="right") - 1
    if idx < 0 or idx >= len(self.values):
        return

    # Increment the bin count
    self.values[idx] += weight_val
    return None<|return|>

def validate_value(value):
    """
    Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    # Ensure the value is a string
    if not isinstance(value, str):
        raise ValidationError(f"Expected a string, got {type(value).__name__}")

    # Retrieve the regular expression to use for validation
    try:
        regex = REGEX
    except NameError:
        raise ValidationError("No regular expression defined for validation.")

    if regex is None:
        raise ValidationError("Regular expression is None.")

    # If the regex is a string, compile it
    if isinstance(regex, str):
        import re
        try:
            regex = re.compile(regex)
        except re.error as exc:
            raise ValidationError(f"Invalid regular expression: {exc}")

    # Ensure we have a compiled pattern with a match method
    if not hasattr(regex, "match"):
        raise ValidationError("Provided regex is not a compiled pattern.")

    # Perform the validation
    if not regex.match(value):
        raise ValidationError(f"Value '{value}' does not match the required pattern.")

    return value<|return|>

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Basic validation
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    # If the manifest is not a dict-like structure, nothing to do
    if not isinstance(last_applied_manifest, dict):
        return last_applied_manifest

    # Helper to update a single key
    def _update_key(key, nested_schema, resp_val):
        if key not in last_applied_manifest:
            # Only set if the response contains the key
            if key in resp_val:
                last_applied_manifest[key] = resp_val[key]
        else:
            # Existing value – recurse if nested
            existing_val = last_applied_manifest[key]
            new_val = resp_val.get(key)
            if isinstance(existing_val, dict) and isinstance(new_val, dict):
                # Delegate to dict updater
                update_last_applied_manifest_dict_from_resp(
                    existing_val, new_val
                )
            elif isinstance(existing_val, list) and isinstance(new_val, list):
                # Recurse into list
                update_last_applied_manifest_list_from_resp(
                    existing_val, nested_schema, new_val
                )

    # Iterate over the observer schema
    for item in observer_schema:
        if isinstance(item, dict):
            # Nested schema: key -> sub-schema
            for key, sub_schema in item.items():
                _update_key(key, sub_schema, response)
        else:
            # Simple key
            _update_key(item, None, response)

    return last_applied_manifest
<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation of the input
    if app is None:
        raise ValueError("The 'app' argument must not be None.")
    if not hasattr(app, "spec"):
        raise AttributeError("The application object must have a 'spec' attribute.")
    spec = app.spec
    if not hasattr(spec, "manifest"):
        raise AttributeError("The application spec must have a 'manifest' attribute.")
    manifest = spec.manifest
    if not isinstance(manifest, (list, tuple)):
        raise TypeError("The application spec.manifest must be a list or tuple of resources.")

    # Existing observer schemas (if any)
    existing_schemas = getattr(spec, "observer_schema", {})
    if existing_schemas is None:
        existing_schemas = {}
    if not isinstance(existing_schemas, dict):
        raise TypeError("The application spec.observer_schema must be a dict if present.")

    default_schemas = {}
    for resource in manifest:
        # Skip non-dict resources
        if not isinstance(resource, dict):
            continue

        kind = resource.get("kind")
        metadata = resource.get("metadata", {})
        name = metadata.get("name")
        namespace = metadata.get("namespace")

        # Skip resources without a kind or name
        if not kind or not name:
            continue

        # Build a unique key for the resource
        key = f"{kind}/{namespace}/{name}" if namespace else f"{kind}/{name}"

        # Skip if a custom observer schema already exists for this resource
        if key in existing_schemas:
            continue

        api_version = resource.get("apiVersion")
        # Construct a minimal default schema
        default_schema = {
            "kind": kind,
            "apiVersion": api_version,
            "metadata": {
                "name": name,
                "namespace": namespace,
            },
            "spec": resource.get("spec", {}),
            "status": resource.get("status", {}),
        }
        default_schemas[key] = default_schema

    return default_schemas<|return|>

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")
    # Retrieve the log; support common attribute names
    log = getattr(self, 'validation_log', None)
    if log is None:
        log = getattr(self, 'log', None)
    if log is None:
        return ''
    # Normalize log to an iterable of strings
    if isinstance(log, str):
        lines = [log]
    elif isinstance(log, (list, tuple, set)):
        lines = [str(item) for item in log]
    elif isinstance(log, dict):
        lines = [str(v) for v in log.values()]
    else:
        # Fallback: try to iterate, otherwise treat as single string
        try:
            lines = [str(item) for item in log]
        except Exception:
            lines = [str(log)]
    # Prepend prefix to each line
    prefixed_lines = [f"{prefix}{line}" for line in lines]
    return "\n".join(prefixed_lines)<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Normalize inputs
    if isinstance(manifest_files, dict):
        manifest_digests = set(manifest_files.values())
    elif isinstance(manifest_files, (list, tuple, set)):
        manifest_digests = set(manifest_files)
    else:
        raise TypeError("manifest_files must be a dict, list, tuple, or set")

    if isinstance(digests_used, (set, list, tuple)):
        used_digests = set(digests_used)
    else:
        raise TypeError("digests_used must be a set, list, or tuple")

    # Check that every digest required by the manifest is actually used
    missing = manifest_digests - used_digests
    if missing:
        raise ValueError(f"Missing digests in usage: {', '.join(sorted(missing))}")

    # Optionally, check that no unused digests are present
    unused = used_digests - manifest_digests
    if unused:
        raise ValueError(f"Unused digests found: {', '.join(sorted(unused))}")

    return True<|return|>

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic sanity checks
    if prior is None:
        raise ValueError("prior cannot be None")
    if not hasattr(prior, "inventory"):
        raise TypeError("prior must have an 'inventory' attribute")
    if not hasattr(self, "inventory"):
        raise TypeError("self must have an 'inventory' attribute")

    # Ensure inventories are dict-like
    if not isinstance(self.inventory, dict):
        raise TypeError("self.inventory must be a dict")
    if not isinstance(prior.inventory, dict):
        raise TypeError("prior.inventory must be a dict")

    # Check that all keys in prior are present in self
    missing_keys = set(prior.inventory.keys()) - set(self.inventory.keys())
    if missing_keys:
        raise ValueError(
            f"prior inventory contains keys not present in current inventory: {missing_keys}"
        )

    # Optionally verify that the values match (prior should be a true prior)
    mismatched = {
        k for k in prior.inventory
        if self.inventory.get(k) != prior.inventory[k]
    }
    if mismatched:
        raise ValueError(
            f"prior inventory values differ from current inventory for keys: {mismatched}"
        )

    # If both objects expose a version attribute, ensure prior is older
    if hasattr(prior, "version") and hasattr(self, "version"):
        try:
            if prior.version >= self.version:
                raise ValueError(
                    f"prior.version ({prior.version}) must be less than current version ({self.version})"
                )
        except TypeError:
            # If versions are not comparable, ignore the check
            pass

    return True<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")
    if version is None:
        raise ValueError("version must not be None")

    # Helper to compare two version strings.
    def _compare_versions(v1, v2):
        try:
            from packaging.version import Version
            return (Version(v1) > Version(v2)) - (Version(v1) < Version(v2))
        except Exception:
            # Fallback: split on non-digit characters and compare numerically.
            import re
            def _split(v):
                parts = re.split(r'\D+', v)
                return [int(p) if p.isdigit() else p for p in parts if p]
            p1, p2 = _split(v1), _split(v2)
            for a, b in zip(p1, p2):
                if isinstance(a, int) and isinstance(b, int):
                    if a != b:
                        return (a > b) - (a < b)
                else:
                    if a != b:
                        return (a > b) - (a < b)
            return len(p1) - len(p2)

    result = {}
    # Case 1: inventory is a dict mapping logical_path -> {version: content_file}
    if isinstance(inventory, dict):
        for logical_path, ver_map in inventory.items():
            if not isinstance(ver_map, dict):
                continue
            for ver, content_file in ver_map.items():
                try:
                    if _compare_versions(ver, version) >= 0:
                        result.setdefault(logical_path, set()).add(content_file)
                except Exception:
                    # Skip entries with unparsable versions
                    continue
    # Case 2: inventory is a list/tuple of (logical_path, version, content_file)
    elif isinstance(inventory, (list, tuple)):
        for entry in inventory:
            if not isinstance(entry, (list, tuple)) or len(entry) < 3:
                continue
            logical_path, ver, content_file = entry[0], entry[1], entry[2]
            try:
                if _compare_versions(ver, version) >= 0:
                    result.setdefault(logical_path, set()).add(content_file)
            except Exception:
                continue
    else:
        raise TypeError("inventory must be a dict or a list/tuple of entries")

    return result<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Validate manifest_files
    if manifest_files is None:
        raise ValueError("manifest_files cannot be None")
    if not isinstance(manifest_files, (set, list, tuple)):
        raise ValueError("manifest_files must be a set, list, or tuple of file names")
    manifest_set = set(manifest_files)

    # Validate fixity
    if fixity is None:
        raise ValueError("fixity cannot be None")
    if not isinstance(fixity, (dict, list, tuple)):
        raise ValueError("fixity must be a dict or a list/tuple of entries")

    seen_files = set()

    if isinstance(fixity, dict):
        for file_name, entry in fixity.items():
            if not isinstance(file_name, str):
                raise ValueError(f"Fixity key '{file_name}' is not a string")
            if file_name not in manifest_set:
                raise ValueError(f"Fixity references unknown file '{file_name}' not in manifest")
            if file_name in seen_files:
                raise ValueError(f"Duplicate fixity entry for file '{file_name}'")
            seen_files.add(file_name)

            if not isinstance(entry, dict):
                raise ValueError(f"Fixity entry for file '{file_name}' must be a dict")
            if 'hash' not in entry or 'algorithm' not in entry:
                raise ValueError(f"Fixity entry for file '{file_name}' missing 'hash' or 'algorithm'")
    else:  # list or tuple
        for idx, entry in enumerate(fixity):
            if not isinstance(entry, dict):
                raise ValueError(f"Fixity entry at index {idx} must be a dict")
            if 'file' not in entry:
                raise ValueError(f"Fixity entry at index {idx} missing 'file' key")
            file_name = entry['file']
            if not isinstance(file_name, str):
                raise ValueError(f"File name in fixity entry at index {idx} is not a string")
            if file_name not in manifest_set:
                raise ValueError(f"Fixity references unknown file '{file_name}' not in manifest")
            if file_name in seen_files:
                raise ValueError(f"Duplicate fixity entry for file '{file_name}'")
            seen_files.add(file_name)

            if 'hash' not in entry or 'algorithm' not in entry:
                raise ValueError(f"Fixity entry for file '{file_name}' missing 'hash' or 'algorithm'")

    # All checks passed
    return True<|return|>

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")
    if not zip_path:
        raise ValueError("zip_path cannot be empty")
    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"File not found: {zip_path}")

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First, collect all XML basenames
            xml_basenames = set()
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                base, ext = os.path.splitext(os.path.basename(name))
                if ext.lower() == '.xml':
                    xml_basenames.add(base)

            # Now group all files that share those basenames
            result = {}
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                base, _ = os.path.splitext(os.path.basename(name))
                if base in xml_basenames:
                    if base not in result:
                        result[base] = {}
                    result[base][name] = zf.read(name)

            return result
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Bad zip file: {zip_path}") from e<|return|>

