def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            # Try lxml xpath
            if hasattr(node, "xpath"):
                results = node.xpath(xpath)
                if results:
                    return results[0]
            # Try BeautifulSoup CSS selector as fallback
            if hasattr(node, "select"):
                results = node.select(xpath)
                if results:
                    return results[0]
            # Try BeautifulSoup find_all with tag name if xpath is simple tag
            if hasattr(node, "find_all"):
                # If xpath is just a tag name without predicates
                if xpath.strip().startswith("<") and xpath.strip().endswith(">"):
                    tag = xpath.strip("<>").strip()
                    results = node.find_all(tag)
                    if results:
                        return results[0]
        except Exception:
            # Ignore errors and continue to next xpath
            continue
    return None<|return|>

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        # In Python 2, encode unicode strings to bytes; in Python 3, leave as is
        if result is not None and not isinstance(result, str):
            try:
                return result.encode()
            except Exception:
                # If encoding fails, return the original result
                return result
        return result
    return inner<|return|>

