    default = "unknown"
    try:
        with open(VERSION_PATH, "r") as f:
            lines = f.readlines()
    except Exception:
        return default

    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" in line:
            _, value = line.split("=", 1)
            value = value.strip()
            # Remove surrounding quotes if present
            if (value.startswith("'") and value.endswith("'")) or (value.startswith('"') and value.endswith('"')):
                value = value[1:-1]
            return value
    # If no assignment found, return the first non-empty line
    for line in lines:
        line = line.strip()
        if line and not line.startswith("#"):
            return line
    return default<|return|>

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate pieces
    if pieces is None:
        raise TypeError("pieces must not be None")
    try:
        iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable")
    pieces_list = list(pieces)
    if not pieces_list:
        raise ValueError("pieces must contain at least one element")
    # Convert each piece to string
    try:
        pieces_str = [str(p) for p in pieces_list]
    except Exception as e:
        raise ValueError(f"Error converting pieces to string: {e}") from e
    # Normalize style
    if style is None:
        raise ValueError("style must not be None")
    style = style.lower()
    # Render based on style
    if style == 'full':
        return '.'.join(pieces_str)
    elif style == 'short':
        return pieces_str[0]
    elif style == 'semantic':
        if len(pieces_str) >= 3:
            return f"{pieces_str[0]}.{pieces_str[1]}.{pieces_str[2]}"
        else:
            return '.'.join(pieces_str)
    elif style == 'numeric':
        try:
            return str(int(''.join(pieces_str)))
        except Exception as e:
            raise ValueError(f"Cannot convert pieces to numeric: {e}") from e
    elif style == 'tuple':
        return str(tuple(pieces_list))
    else:
        raise ValueError(f"Unsupported style: {style}")<|return|>

