def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate parameter types
    if not isinstance(validate_objects, bool):
        raise TypeError('validate_objects must be a bool')
    if not isinstance(check_digests, bool):
        raise TypeError('check_digests must be a bool')
    if not isinstance(show_warnings, bool):
        raise TypeError('show_warnings must be a bool')

    # Helper to recursively iterate over the hierarchy
    def _iter(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from _iter(v)
        elif isinstance(obj, list):
            for v in obj:
                yield from _iter(v)
        else:
            yield obj

    # Determine the root of the hierarchy
    root = getattr(self, '_root', None)
    if root is None:
        # If no root attribute, try a generic attribute
        root = getattr(self, 'root', None)
    if root is None:
        # Nothing to validate
        return 0, 0

    num_objects = 0
    good_objects = 0

    for obj in _iter(root):
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            validate_method = getattr(obj, 'validate', None)
            if callable(validate_method):
                try:
                    result = validate_method()
                    if result is False:
                        is_valid = False
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f'Warning: validation failed for {obj!r} with exception: {exc}')
            else:
                # If no validate method, assume valid
                pass

        # Check digests if requested
        if is_valid and check_digests:
            # Attempt to compute a digest of the object's data
            data = getattr(obj, 'data', None)
            expected_digest = getattr(obj, 'digest', None)
            if data is not None and expected_digest is not None:
                try:
                    import hashlib
                    # Ensure data is bytes; if string, encode
                    if isinstance(data, str):
                        data_bytes = data.encode('utf-8')
                    elif isinstance(data, bytes):
                        data_bytes = data
                    else:
                        # Try to convert to string representation
                        data_bytes = str(data).encode('utf-8')
                    actual_digest = hashlib.sha256(data_bytes).hexdigest()
                    if actual_digest != expected_digest:
                        is_valid = False
                        if show_warnings:
                            print(f'Warning: digest mismatch for {obj!r}')
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f'Warning: digest check failed for {obj!r} with exception: {exc}')

        if is_valid:
            good_objects += 1

    return num_objects, good_objects<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version:
        return ""
    if not version.isdigit():
        # Cannot parse non-numeric version; return as is
        return version
    zero_prefixed = version.startswith("0") and len(version) > 1
    try:
        num = int(version)
    except ValueError:
        return version
    new_num = num + 1
    new_str = str(new_num)
    if zero_prefixed:
        width = len(version)
        if len(new_str) < width:
            new_str = new_str.zfill(width)
    return new_str<|return|>

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
    except Exception as exc:
        return f"import error: {exc}"

    if not os.path.exists(path):
        return f"path does not exist: {path}"

    if os.path.isfile(path):
        return 'file'

    if os.path.isdir(path):
        namaste_path = os.path.join(path, "0=*")
        if not os.path.isfile(namaste_path):
            return f"missing Namaste file in directory: {path}"
        try:
            with open(namaste_path, 'r', encoding='utf-8') as f:
                content = f.read().strip()
        except Exception as exc:
            return f"error reading Namaste file: {exc}"
        if content == 'root':
            return 'root'
        if content == 'object':
            return 'object'
        return f"unknown Namaste content: {content}"

    return f"unknown path type: {path}"
<|return|>

