def parse_arguments(*arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    """
    import argparse
    import sys

    # Create a parser that captures all remaining arguments
    parser = argparse.ArgumentParser()
    parser.add_argument('args', nargs=argparse.REMAINDER, help='Command line arguments')

    # Normalize the input: if a single list/tuple is passed, use it directly
    if len(arguments) == 1 and isinstance(arguments[0], (list, tuple)):
        args_list = list(arguments[0])
    else:
        args_list = list(arguments)

    # If no explicit arguments were provided, fall back to sys.argv[1:]
    if not args_list:
        args_list = sys.argv[1:]

    try:
        return parser.parse_args(args_list)
    except Exception as exc:
        # Re‑raise with a clearer message for debugging
        raise ValueError(f"Failed to parse arguments {args_list!r}: {exc}") from exc<|return|>

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    if parser is None:
        raise ValueError("parser cannot be None")
    # Ensure the object looks like an ArgumentParser
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in parser._actions:
        # action.option_strings may be empty for positional arguments
        for opt in getattr(action, "option_strings", []):
            if isinstance(opt, str) and opt.startswith("-"):
                flags.append(opt)
    return " ".join(flags)<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Expected an iterable of dictionaries, got None")
    try:
        iterator = iter(dicts)
    except TypeError as exc:
        raise TypeError("Expected an iterable of dictionaries") from exc

    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for key {key!r} must be numeric, got {type(value).__name__}")
            result[key] = result.get(key, 0) + value
    return result<|return|>

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None check
    if val is None:
        return True
    # Only strings are considered for "None" representations
    if isinstance(val, str):
        stripped = val.strip()
        # Empty string or common textual representations of None
        if not stripped:
            return True
        lowered = stripped.lower()
        if lowered in {"none", "null", "n/a", "na", "nil"}:
            return True
    return False<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two symbols")
    for idx, sym in enumerate(alphabet):
        if not isinstance(sym, str) or len(sym) != 1:
            raise ValueError(f"alphabet element at index {idx} must be a single-character string")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result
<|return|>

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string")

    for key, flow in flow_params.items():
        # Handle nested dicts
        if isinstance(flow, dict):
            if register_value in flow:
                flow[register_value] = register_number
        # Handle list of dicts
        elif isinstance(flow, list):
            for item in flow:
                if isinstance(item, dict) and register_value in item:
                    item[register_value] = register_number
    return flow_params<|return|>

