def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type")
    seen = set()
    queue = [cls]
    while queue:
        current = queue.pop()
        if current in seen:
            continue
        seen.add(current)
        for sub in current.__subclasses__():
            if sub not in seen:
                queue.append(sub)
    seen.discard(cls)
    return seen<|return|>

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must contain at least one symbol")
    base = len(alphabet)
    # Build a mapping from symbol to its numeric value
    try:
        mapping = {symbol: idx for idx, symbol in enumerate(alphabet)}
    except Exception as exc:
        raise ValueError(f"Failed to build alphabet mapping: {exc}") from exc

    if not string:
        raise ValueError("input string must not be empty")

    result = 0
    for char in string:
        if char not in mapping:
            raise ValueError(f"Character '{char}' not found in alphabet")
        result = result * base + mapping[char]
    return result<|return|>

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Ensure destination_path is a Path instance
    if not isinstance(destination_path, Path):
        destination_path = Path(destination_path)

    # Check if destination exists
    if destination_path.exists():
        if not destination_path.is_dir():
            raise OSError(f"Destination path {destination_path} exists and is not a directory.")
        # If directory is not empty, raise to avoid accidental overwrite
        if any(destination_path.iterdir()):
            raise OSError(f"Destination directory {destination_path} is not empty.")
    else:
        # Create the directory
        try:
            destination_path.mkdir(parents=True, exist_ok=False)
        except Exception as exc:
            raise OSError(f"Failed to create destination directory {destination_path}: {exc}") from exc

    # Download the archive to a temporary file
    temp_file = None
    try:
        with requests.get(url, stream=True, timeout=30) as resp:
            resp.raise_for_status()
            # Create a temporary file to store the downloaded archive
            temp_file = Path(tempfile.mkstemp(suffix=".tar.gz")[1])
            with temp_file.open("wb") as f:
                for chunk in resp.iter_content(chunk_size=8192):
                    if chunk:
                        f.write(chunk)
    except requests.RequestException as exc:
        raise RuntimeError(f"Failed to download archive from {url}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error during download: {exc}") from exc

    # Extract the archive
    try:
        with tarfile.open(temp_file, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except tarfile.TarError as exc:
        raise RuntimeError(f"Failed to extract archive {temp_file} to {destination_path}: {exc}") from exc
    finally:
        # Clean up the temporary file
        if temp_file and temp_file.exists():
            try:
                temp_file.unlink()
            except Exception:
                pass

    return destination_path
<|return|>

