def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError(f"Expected a string, got {type(name).__name__}")
    if len(name) <= 1:
        return name
    # Handle double-quoted strings
    if name.startswith('"') and name.endswith('"'):
        inner = name[1:-1]
        # Unescape escaped quotes and backslashes
        inner = inner.replace(r'\"', '"').replace(r'\\', '\\')
        return inner
    # Handle angle-bracketed strings
    if name.startswith('<') and name.endswith('>'):
        return name[1:-1]
    return name<|return|>

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    import shlex
    import subprocess

    if s is None:
        raise TypeError("split() argument must be a string, not None")

    if not isinstance(s, str):
        raise TypeError(f"split() argument must be a string, not {type(s).__name__}")

    # Resolve platform
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    elif platform not in (0, 1):
        raise ValueError("platform must be 'this', 0 (Windows), or 1 (POSIX)")

    try:
        if platform == 1:  # POSIX
            return shlex.split(s, posix=True)
        else:  # Windows
            # subprocess._splitargs_windows is an internal helper that implements
            # the Windows command-line parsing rules. It is available in CPython
            # and provides the desired behavior.
            return subprocess._splitargs_windows(s)
    except Exception as exc:
        # Wrap any unexpected exception to provide a clear error message
        raise RuntimeError(f"Failed to split command line: {exc}") from exc<|return|>

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stderr=subprocess.STDOUT,
            universal_newlines=True
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Git command failed: {e.output}") from e
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)<|return|>

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == 'always':
        return None
    if not isinstance(frequency, str):
        raise ValueError('Frequency must be a string or None')
    s = frequency.strip()
    parts = s.split()
    if len(parts) != 2:
        raise ValueError(f'Cannot parse frequency: {frequency}')
    num_str, unit = parts
    try:
        num = int(num_str)
    except ValueError:
        raise ValueError(f'Invalid number in frequency: {num_str}')
    unit = unit.lower()
    if unit in ('week', 'weeks'):
        return datetime.timedelta(weeks=num)
    elif unit in ('day', 'days'):
        return datetime.timedelta(days=num)
    elif unit in ('hour', 'hours'):
        return datetime.timedelta(hours=num)
    elif unit in ('minute', 'minutes'):
        return datetime.timedelta(minutes=num)
    elif unit in ('second', 'seconds'):
        return datetime.timedelta(seconds=num)
    elif unit in ('month', 'months'):
        return datetime.timedelta(days=num * 30)
    elif unit in ('year', 'years'):
        return datetime.timedelta(days=num * 365)
    else:
        raise ValueError(f'Unknown time unit: {unit}')<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for info in infos:
        family, _, _, _, sockaddr = info
        addr = sockaddr[0]
        if family == socket.AF_INET:
            if addr == "127.0.0.1" or addr.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            if addr in ("::1", "0:0:0:0:0:0:0:1"):
                return True
    return False<|return|>

def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    if find_paths is None:
        return []

    if not hasattr(find_paths, '__iter__') or isinstance(find_paths, (str, bytes)):
        raise TypeError(f"find_paths must be an iterable of strings, got {type(find_paths)}")

    transformed = []
    for item in find_paths:
        if item is None:
            continue
        # Ensure we are working with a string
        if isinstance(item, (bytes, bytearray)):
            try:
                item = item.decode()
            except Exception as exc:
                raise ValueError(f"Unable to decode bytes item {item!r}") from exc
        if not isinstance(item, str):
            raise TypeError(f"Each find_path must be a string, got {type(item)}")

        # If the item already contains a scheme prefix (e.g., 'sh:' or 'pp:'),
        # leave it unchanged. We assume a scheme is indicated by a colon.
        if ':' in item:
            transformed.append(item)
        else:
            # Escape any special glob characters? The example does not escape,
            # so we simply wrap the fragment in a pattern.
            transformed.append(f'sh:**/*{item}*/**')
    return transformed<|return|>

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # If the file exists and we are not allowed to overwrite, exit early
    if not overwrite and os.path.isfile(config_filename):
        return

    # Ensure the directory exists
    dir_name = os.path.dirname(os.path.abspath(config_filename))
    if dir_name and not os.path.isdir(dir_name):
        try:
            os.makedirs(dir_name, exist_ok=True)
        except OSError as exc:
            # If the directory still does not exist after attempting to create it, re-raise
            if not os.path.isdir(dir_name):
                raise OSError(f"Failed to create directory '{dir_name}': {exc}") from exc

    # Write the rendered configuration to the file
    try:
        with open(config_filename, 'w') as f:
            f.write(rendered_config)
        # Set the file permissions
        os.chmod(config_filename, mode)
    except OSError as exc:
        raise OSError(f"Failed to write configuration to '{config_filename}': {exc}") from exc<|return|>

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str):
        raise ValueError("image_href must be a string")

    parsed = urllib.parse.urlparse(image_href)

    # Validate scheme
    if parsed.scheme not in ("http", "https"):
        raise ValueError(f"Unsupported URL scheme: {parsed.scheme!r}")

    netloc = parsed.netloc
    if not netloc:
        raise ValueError("URL must contain a network location")

    use_ssl = parsed.scheme == "https"

    path = parsed.path
    if not path:
        raise ValueError("URL must contain a path")

    # Strip trailing slash if present
    if path.endswith("/"):
        path = path[:-1]

    filename = path.split("/")[-1]
    if not filename:
        raise ValueError("URL path does not contain a filename")

    # Extract image id (basename without extension)
    if "." in filename:
        image_id = filename.rsplit(".", 1)[0]
    else:
        image_id = filename

    if not image_id:
        raise ValueError("Could not extract image id from URL")

    return image_id, netloc, use_ssl<|return|>

