def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    config_map = {}
    error_records = []
    logger = logging.getLogger(__name__)

    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                raw = f.read()
            # Determine parser based on file extension
            if fname.lower().endswith('.toml'):
                try:
                    import toml
                except ImportError as e:
                    raise ImportError("toml module is required for .toml files") from e
                cfg = toml.loads(raw)
            elif fname.lower().endswith(('.yaml', '.yml')):
                try:
                    import yaml
                except ImportError as e:
                    raise ImportError("yaml module is required for .yaml/.yml files") from e
                cfg = yaml.safe_load(raw)
            elif fname.lower().endswith('.json'):
                import json
                cfg = json.loads(raw)
            else:
                # Try yaml first, then json
                try:
                    import yaml
                    cfg = yaml.safe_load(raw)
                except Exception:
                    import json
                    cfg = json.loads(raw)
            if not isinstance(cfg, dict):
                raise ValueError("Parsed configuration is not a dictionary")
            # Apply overrides if provided
            if overrides and isinstance(overrides, dict):
                cfg.update(overrides)
            # Resolve environment variables if requested
            if resolve_env:
                def _resolve(val):
                    if isinstance(val, str):
                        return os.path.expandvars(val)
                    if isinstance(val, dict):
                        return {k: _resolve(v) for k, v in val.items()}
                    if isinstance(val, list):
                        return [_resolve(v) for v in val]
                    return val
                cfg = _resolve(cfg)
            config_map[fname] = cfg
        except Exception as e:
            # Create a LogRecord for the error
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Failed to load configuration '{fname}': {e}",
                args=(),
                exc_info=e
            )
            error_records.append(record)
    return config_map, error_records<|return|>

