@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Helper to collect handlers from class attributes
        def _collect_handlers():
            handlers = {}
            # Prefer explicit mapping if defined
            if hasattr(cls, "PROTOCOL_HANDLERS") and isinstance(cls.PROTOCOL_HANDLERS, dict):
                for ver, handler in cls.PROTOCOL_HANDLERS.items():
                    if isinstance(ver, tuple) and len(ver) == 2 and all(isinstance(v, int) for v in ver):
                        handlers[ver] = handler
                return handlers
            # Fallback: introspect class attributes
            for name, obj in cls.__dict__.items():
                if isinstance(obj, type):
                    # Look for a _protocol_version attribute
                    ver = getattr(obj, "_protocol_version", None)
                    if isinstance(ver, tuple) and len(ver) == 2 and all(isinstance(v, int) for v in ver):
                        handlers[ver] = obj
            return handlers

        all_handlers = _collect_handlers()

        if protocol_version is None:
            return all_handlers

        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple of (major, minor)")
        if len(protocol_version) != 2 or not all(isinstance(v, int) for v in protocol_version):
            raise TypeError("protocol_version must be a tuple of two integers (major, minor)")

        return {protocol_version: all_handlers[protocol_version]} if protocol_version in all_handlers else {}<|return|>

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Validate that values is an iterable of strings and not a single string
    if values is None:
        raise TypeError("values must be an iterable of strings")
    if isinstance(values, str):
        raise TypeError("values must be an iterable of strings, not a single string")
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings")

    bookmarks = []
    for raw in iterator:
        if not isinstance(raw, str):
            raise TypeError(f"Bookmark value must be a string, got {type(raw).__name__}")
        raw = raw.strip()
        if not raw:
            continue
        try:
            # Prefer a dedicated from_raw method if available
            if hasattr(Bookmark, "from_raw"):
                bookmark = Bookmark.from_raw(raw)
            else:
                bookmark = Bookmark(raw)
        except Exception as exc:
            raise ValueError(f"Failed to parse bookmark from raw value '{raw}': {exc}") from exc
        bookmarks.append(bookmark)

    # Construct the Bookmarks instance; assume the constructor accepts a list of Bookmark objects
    return cls(bookmarks)<|return|>

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    # Import necessary modules locally to avoid top-level imports
    try:
        from zope.interface import Invalid
    except Exception:
        # If zope.interface is not available, raise a generic exception
        raise RuntimeError("zope.interface is required for verifyObject")
    import inspect

    errors = []

    # Step 1: Check that candidate claims to provide iface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"Candidate {candidate!r} does not claim to provide {iface!r}")
        except Exception as exc:
            errors.append(f"Error checking providedBy for {candidate!r}: {exc}")

    # Helper to get attribute from candidate (instance or class)
    def get_attr(obj, name):
        try:
            return getattr(obj, name)
        except AttributeError:
            return None

    # Step 2: Check methods
    for name in iface.methods():
        iface_method = iface[name]
        cand_attr = get_attr(candidate, name)
        if cand_attr is None:
            errors.append(f"Missing method '{name}' required by {iface!r}")
            continue
        if not callable(cand_attr):
            errors.append(f"Attribute '{name}' is not callable in {candidate!r}")
            continue
        # Compare signatures
        try:
            iface_sig = inspect.signature(iface_method)
            cand_sig = inspect.signature(cand_attr)
            # For bound methods, the first parameter is 'self'; ignore it for comparison
            iface_params = list(iface_sig.parameters.values())
            cand_params = list(cand_sig.parameters.values())
            # If method is bound, remove first param
            if inspect.ismethod(cand_attr) or inspect.isfunction(cand_attr):
                # For bound methods, the first param is 'self' in both signatures
                if iface_params and iface_params[0].name == 'self':
                    iface_params = iface_params[1:]
                if cand_params and cand_params[0].name == 'self':
                    cand_params = cand_params[1:]
            if len(iface_params) != len(cand_params):
                errors.append(
                    f"Signature mismatch for method '{name}': "
                    f"expected {len(iface_params)} params, got {len(cand_params)}"
                )
                continue
            for ip, cp in zip(iface_params, cand_params):
                if ip.kind != cp.kind or ip.name != cp.name:
                    errors.append(
                        f"Signature mismatch for method '{name}': "
                        f"parameter '{ip.name}' kind {ip.kind} vs '{cp.name}' kind {cp.kind}"
                    )
                    break
        except Exception as exc:
            errors.append(f"Error inspecting signature of method '{name}': {exc}")

    # Step 3: Check attributes
    for name in iface.attributes():
        if get_attr(candidate, name) is None:
            errors.append(f"Missing attribute '{name}' required by {iface!r}")

    # Raise errors if any
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True
<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit __metaclass__ must be a type")
        return explicit_mc
    if not bases:
        return type
    metaclasses = set()
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"base {base!r} is not a class")
        metaclasses.add(type(base))
    if len(metaclasses) == 1:
        return metaclasses.pop()
    for candidate in metaclasses:
        if all(issubclass(candidate, other) for other in metaclasses):
            return candidate
    names = ", ".join(m.__name__ for m in metaclasses)
    raise TypeError(f"metaclass conflict: {names}")<|return|>

