def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Ensure request and body exist
    if request is None:
        return False
    body = getattr(request, "body", None)
    if body is None:
        return False

    # Try to detect a private (encrypted) payload
    try:
        # decode_if_bytes should convert bytes to str if needed
        data = json.loads(decode_if_bytes(body))
        if isinstance(data, dict) and "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # Try to detect a public (XML) payload
    try:
        # encode_if_text should convert str to bytes if needed
        xml = etree.fromstring(encode_if_text(body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass

    return False<|return|>

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Attempt to obtain the request path from common attributes
        path = None
        if hasattr(request, "path"):
            path = getattr(request, "path")
        elif hasattr(request, "url"):
            path = getattr(request, "url")
        elif hasattr(request, "META"):
            path = request.META.get("PATH_INFO")
        if not isinstance(path, str):
            return False

        # Matrix API endpoints are prefixed with "/_matrix/"
        if not path.startswith("/_matrix/"):
            return False

        # Optionally check the content type to increase confidence
        content_type = None
        if hasattr(request, "headers"):
            content_type = request.headers.get("Content-Type") or request.headers.get("content-type")
        if not content_type and hasattr(request, "META"):
            content_type = request.META.get("CONTENT_TYPE")
        if not content_type and hasattr(request, "content_type"):
            content_type = getattr(request, "content_type")

        # If a content type is present, it should be JSON for Matrix requests
        if content_type and not content_type.startswith("application/json"):
            return False

        return True
    except Exception:
        # Any unexpected error should result in a conservative False
        return False<|return|>

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if dt is None:
        return None
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime instance")
    # If the datetime is timezone-aware, convert it to UTC and format with a trailing 'Z'
    if dt.tzinfo is not None:
        try:
            dt_utc = dt.astimezone(datetime.timezone.utc)
        except Exception:
            # Fallback: assume the datetime is already in UTC
            dt_utc = dt
        return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    # Naive datetime: format without timezone information
    return dt.strftime("%Y-%m-%dT%H:%M:%S")<|return|>

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if text is None:
        return ''
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # Regular expression to find http/https URLs
    url_re = re.compile(r'(https?://[^\s]+)')
    def _replace(match):
        url = match.group(0)
        # Basic sanitization: strip trailing punctuation
        stripped = url.rstrip('.,;:!?')
        trailing = url[len(stripped):]
        # Build the link with attributes
        link = f'<a href="{stripped}" target="_blank" rel="noopener noreferrer">{stripped}</a>'
        return link + trailing
    try:
        return url_re.sub(_replace, text)
    except re.error:
        # If regex fails, return original text
        return text
<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    Returns the value of the 'Content-Type' header if present, otherwise None.
    """
    # Validate URL scheme
    try:
        scheme, netloc, path, query, fragment = urllib.parse.urlsplit(url)
    except Exception:
        return None

    if scheme not in ("http", "https", "ftp", "ftps"):
        return None

    # For FTP/FTPS, HEAD is not applicable; return None
    if scheme in ("ftp", "ftps"):
        return None

    # Prepare a HEAD request
    req = urllib.request.Request(url, method="HEAD")
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            # Some servers may return 405 Method Not Allowed; treat as no content type
            if hasattr(resp, "code") and resp.code >= 400:
                return None
            return resp.info().get("Content-Type")
    except Exception:
        return None<|return|>

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an ElementTree Element") from exc
    result = {}
    for child in children:
        tag = child.tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Import here to avoid module-level imports
    from urllib.parse import urlparse, urljoin

    # Validate the base URL
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise ValueError(f"Invalid base URL: {url}")

    # Determine the NodeInfo document path
    if document_path is None:
        document_path = "/.well-known/nodeinfo/1.0"
    if not isinstance(document_path, str):
        raise TypeError("document_path must be a string")
    # Ensure the path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path

    # Build the full URL to the NodeInfo document
    base = f"{parsed.scheme}://{parsed.netloc}"
    href = urljoin(base, document_path)

    # Construct the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document or not isinstance(document, str):
        return None
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        hcard_url = None
        for link in data.get("links", []):
            if link.get("rel") == "http://webfinger.net/rel/hcard":
                hcard_url = link.get("href")
                break
        return {"subject": subject, "aliases": aliases, "hcard_url": hcard_url}
    except Exception:
        # Fallback to XRD (XML)
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(document)
            ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            subject_el = root.find("xrd:Subject", ns)
            subject = subject_el.text if subject_el is not None else None
            aliases = [a.text for a in root.findall("xrd:Alias", ns) if a.text]
            hcard_url = None
            for link in root.findall("xrd:Link", ns):
                if link.attrib.get("rel") == "http://webfinger.net/rel/hcard":
                    hcard_url = link.attrib.get("href")
                    break
            return {"subject": subject, "aliases": aliases, "hcard_url": hcard_url}
        except Exception:
            return None<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Validate handle format
    if not isinstance(handle, str) or "@" not in handle:
        return None
    try:
        host = handle.split("@", 1)[1]
        if not host:
            return None
    except Exception:
        return None

    # Construct the webfinger URL
    try:
        from urllib.parse import quote
        url = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"
    except Exception:
        return None

    # Attempt to fetch the document
    try:
        with urllib.request.urlopen(url) as response:
            # Read and decode the response
            return response.read().decode("utf-8")
    except Exception:
        return None<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except Exception:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None

    document, code, exception = fetch_document(
        host=host,
        path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if exception:
        return None
    if document:
        return parse_diaspora_webfinger(document)

    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None

    try:
        link = hostmeta.find_link(rels="lrdd")
    except Exception:
        return None
    if not link or not getattr(link, "template", None):
        return None

    url = link.template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception or not document:
        return None

    return parse_diaspora_webfinger(document)<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    file_list = []
    if not settings_dirs:
        return file_list
    # Normalize settings_dirs to an iterable of directory paths
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except TypeError:
            return file_list
    # Default pattern if none provided
    if not spec_option:
        spec_option = "*"
    for d in dirs:
        try:
            if not os.path.isdir(d):
                continue
            for fname in os.listdir(d):
                full_path = os.path.join(d, fname)
                if not os.path.isfile(full_path):
                    continue
                if fnmatch.fnmatch(fname, spec_option):
                    file_list.append(full_path)
        except OSError:
            continue
    return sorted(file_list)<|return|>

