@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Ensure we have content to validate
        if spec_content is None:
            raise IRValidatorException("No spec content provided")

        # If the content is a string, attempt to parse it as YAML
        if isinstance(spec_content, str):
            try:
                import yaml
                spec = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"YAML parsing error: {exc}") from exc
        elif isinstance(spec_content, bytes):
            try:
                import yaml
                spec = yaml.safe_load(spec_content.decode('utf-8'))
            except Exception as exc:
                raise IRValidatorException(f"YAML parsing error: {exc}") from exc
        else:
            # Assume it is already a Python object (e.g., dict)
            spec = spec_content

        # The spec must be a mapping
        if not isinstance(spec, dict):
            raise IRValidatorException("Spec content must be a mapping (dictionary)")

        # Determine required fields: use class attribute if defined, otherwise a sensible default
        required_fields = getattr(cls, "REQUIRED_FIELDS", None)
        if required_fields is None:
            # Default required fields for a generic spec
            required_fields = ["name", "type", "spec"]

        # Validate presence of each required field
        missing = [field for field in required_fields if field not in spec]
        if missing:
            missing_str = ", ".join(missing)
            raise IRValidatorException(f"Missing required field(s): {missing_str}")

        return spec<|return|>

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        # Ensure a file path was provided
        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        # Resolve the path and check existence
        try:
            path = Path(yaml_file)
        except Exception as e:
            raise IRValidatorException(f"Invalid file path: {e}")

        if not path.is_file():
            raise IRValidatorException(f"File not found: {yaml_file}")

        # Load the YAML content
        try:
            with path.open("r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except yaml.YAMLError as ye:
            raise IRValidatorException(f"Error parsing YAML file: {ye}")
        except Exception as e:
            raise IRValidatorException(f"Unexpected error reading file: {e}")

        # Basic sanity checks
        if data is None:
            raise IRValidatorException("YAML file is empty or contains no data")
        if not isinstance(data, dict):
            raise IRValidatorException("YAML root must be a mapping (dictionary)")

        # Validate required fields if the class defines them
        required_fields = getattr(cls, "REQUIRED_FIELDS", None)
        if required_fields:
            missing = [field for field in required_fields if field not in data]
            if missing:
                raise IRValidatorException(
                    f"Missing required field(s) in YAML file: {', '.join(missing)}"
                )

        return data<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        raise TypeError('parser_dict must be a dict')

    def _resolve(d):
        resolved = {}
        for key, val in d.items():
            # Handle include directive
            if isinstance(val, dict) and 'include' in val:
                inc = val['include']
                if isinstance(inc, str):
                    inc = [inc]
                if not isinstance(inc, (list, tuple)):
                    raise TypeError(f"include value for key '{key}' must be a string or list/tuple of strings")
                for inc_key in inc:
                    if inc_key not in self.spec:
                        raise KeyError(f"Included group '{inc_key}' not found in spec")
                    inc_val = self.spec[inc_key]
                    if not isinstance(inc_val, dict):
                        raise ValueError(f"Included group '{inc_key}' is not a dict")
                    # Recursively resolve nested includes
                    resolved.update(_resolve(inc_val))
            else:
                # Recursively resolve nested dicts that are not include directives
                if isinstance(val, dict):
                    resolved[key] = _resolve(val)
                else:
                    resolved[key] = val
        return resolved

    return _resolve(parser_dict)<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    try:
        # Helper to fetch value from spec if available
        def _spec_value(name):
            if hasattr(self, "spec") and self.spec is not None:
                try:
                    return self.spec.get(name)
                except Exception:
                    # spec might not support get or key might be missing
                    return None
            return None

        for arg in self.args:
            if not isinstance(arg, _BaseOpt):
                continue

            # Start with value from spec
            value = _spec_value(arg.name)

            # If spec didn't provide a value, fall back to the option's default
            if value is None and not isinstance(arg.default, NoDefault):
                value = arg.default

            # Handle nested dictionary options
            if isinstance(arg, DictOption) and arg.scheme:
                # Get defaults from the nested scheme
                nested_defaults = arg.scheme.get_spec_defaults()
                # If spec provided a dict, merge it with nested defaults
                spec_dict = _spec_value(arg.name)
                if isinstance(spec_dict, dict):
                    # Merge spec dict over nested defaults
                    merged = dict(nested_defaults)
                    merged.update(spec_dict)
                    value = merged
                else:
                    value = nested_defaults

            if value is not None:
                defaults[arg.name] = value
    except Exception as exc:
        # Re-raise with context to aid debugging
        raise RuntimeError(f"Error resolving spec defaults: {exc}") from exc
    return defaults<|return|>

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    import warnings
    if not isinstance(cli_args, dict):
        raise TypeError("cli_args must be a dict")
    if not isinstance(answer_file_args, dict):
        raise TypeError("answer_file_args must be a dict")
    deprecated = getattr(self, "deprecated_args", None)
    if deprecated is None:
        raise AttributeError("Instance missing 'deprecated_args' attribute")
    if not isinstance(deprecated, dict):
        raise TypeError("'deprecated_args' must be a dict mapping old names to new names")
    for arg in cli_args:
        if arg in deprecated:
            warnings.warn(
                f"Argument '{arg}' is deprecated; use '{deprecated[arg]}' instead.",
                DeprecationWarning,
                stacklevel=2,
            )
    for arg in answer_file_args:
        if arg in deprecated:
            warnings.warn(
                f"Argument '{arg}' is deprecated; use '{deprecated[arg]}' instead.",
                DeprecationWarning,
                stacklevel=2,
            )<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Ensure we have a mapping of arguments
    if args is None:
        raise ValueError("No arguments provided")
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")

    # Retrieve the list/set of required argument names
    required = getattr(self, 'required_args', None)
    if not required:
        # Nothing to validate
        return

    # Normalize required to an iterable of names
    if isinstance(required, (list, tuple, set)):
        required_names = required
    else:
        # If it's a dict, assume keys are the required names
        required_names = required.keys()

    # Find any missing required arguments
    missing = [name for name in required_names if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")<|return|>

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        if not options_spec:
            return required
        for opt in options_spec:
            # Skip if not a mapping or missing name
            if not isinstance(opt, dict):
                continue
            name = opt.get('name')
            if not name:
                continue
            cond = opt.get('required_when')
            if cond is None:
                continue
            try:
                matched = False
                if callable(cond):
                    # Pass args to the callable
                    matched = bool(cond(args))
                elif isinstance(cond, dict):
                    # Mapping of command names to truthy values
                    matched = bool(cond.get(command_name))
                elif isinstance(cond, (list, tuple, set)):
                    # List of command names that trigger requirement
                    matched = command_name in cond
                else:
                    # Any truthy value is considered a match
                    matched = bool(cond)
                if matched:
                    required.append(name)
            except Exception:
                # If condition evaluation fails, ignore this option
                continue
        return required<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure args is a mapping of argument names to values
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Retrieve the argument specifications from the parsed YAML
    arg_specs = self.parsed_yaml.get('args', {})
    if not isinstance(arg_specs, dict):
        raise TypeError(f"parsed_yaml['args'] must be a dict, got {type(arg_specs).__name__}")

    for arg_name, arg_value in args.items():
        # Skip if the argument is not present in the spec
        spec = arg_specs.get(arg_name)
        if spec is None:
            continue

        # Only validate if a length constraint is defined
        max_len = spec.get('length')
        if max_len is None:
            continue

        # Validate that the max_len is a non-negative integer
        if not isinstance(max_len, int):
            raise TypeError(
                f"Length constraint for argument '{arg_name}' must be an int, "
                f"got {type(max_len).__name__}"
            )
        if max_len < 0:
            raise ValueError(
                f"Length constraint for argument '{arg_name}' must be non-negative, "
                f"got {max_len}"
            )

        # Skip validation for None values
        if arg_value is None:
            continue

        # Attempt to get the length of the argument value
        try:
            value_len = len(arg_value)
        except TypeError:
            # If the value has no length, skip validation
            continue

        if value_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {value_len} exceeds maximum allowed {max_len}"
            )<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure args is a mapping
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

    # Retrieve argument definitions from parsed YAML
    arg_defs = self.parsed_yaml.get('args', {})
    if not arg_defs:
        return  # nothing to validate

    # Prepare a list of (arg_name, attrs) tuples
    if isinstance(arg_defs, dict):
        arg_items = arg_defs.items()
    else:
        # Assume a list of single‑item dicts
        arg_items = []
        for item in arg_defs:
            if isinstance(item, dict) and len(item) == 1:
                arg_items.append(next(iter(item.items())))
            else:
                # Skip malformed entries
                continue

    for arg_name, attrs in arg_items:
        if not isinstance(attrs, dict):
            continue
        if 'choices' not in attrs:
            continue

        choices = attrs['choices']
        # Normalize choices to a sequence
        if isinstance(choices, (str, bytes)):
            # Treat a string as a single choice
            choices = (choices,)
        elif not isinstance(choices, (list, tuple, set)):
            # Unsupported type; skip validation for this arg
            continue

        if arg_name in args:
            value = args[arg_name]
            if value not in choices:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value!r}. "
                    f"Expected one of {choices!r}."
                )<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the instance has min and max attributes
    if not hasattr(self, 'min') or not hasattr(self, 'max'):
        raise AttributeError("Instance must have 'min' and 'max' attributes")
    min_val = self.min
    max_val = self.max
    if min_val is None or max_val is None:
        raise ValueError("Both 'min' and 'max' must be set")
    if min_val > max_val:
        raise ValueError("'min' must be less than or equal to 'max'")

    # Determine how to iterate over args
    if isinstance(args, dict):
        iterable = args.items()
        key_name = "key"
    else:
        try:
            iter(args)
        except TypeError:
            raise TypeError("args must be an iterable or a dict")
        iterable = enumerate(args)
        key_name = "index"

    for key, val in iterable:
        if val is None:
            raise TypeError(f"Argument {key_name} {key!r} is None, expected numeric value")
        if not isinstance(val, (int, float)):
            raise TypeError(f"Argument {key_name} {key!r} is not numeric: {val!r}")
        if val < min_val or val > max_val:
            raise ValueError(
                f"Argument {key_name} {key!r} with value {val} is out of bounds "
                f"[{min_val}, {max_val}]"
            )
    return args<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of required string parameters
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non-empty string")

    # Normalise spec_option to a dict if possible
    if spec_option is None:
        spec_option = {}
    elif not isinstance(spec_option, dict):
        # If spec_option is a callable or other type, wrap it
        spec_option = {"type": spec_option}

    # Define a lightweight complex argument type class
    class ComplexArgumentType:
        def __init__(self, subcommand, type_name, option_name, spec_option):
            self.subcommand = subcommand
            self.type_name = type_name
            self.option_name = option_name
            self.spec_option = spec_option

        def parse(self, value):
            """Parse the raw string value into the complex type."""
            try:
                if isinstance(self.spec_option, dict):
                    type_func = self.spec_option.get("type", str)
                    # Resolve string names to actual callables if needed
                    if isinstance(type_func, str):
                        type_func = globals().get(type_func, str)
                    return type_func(value)
                # Fallback: return the raw value
                return value
            except Exception as exc:
                raise ValueError(
                    f"Failed to parse value '{value}' for option "
                    f"'{self.option_name}': {exc}"
                ) from exc

        def __repr__(self):
            return (
                f"<ComplexArgumentType subcommand={self.subcommand!r} "
                f"type_name={self.type_name!r} option_name={self.option_name!r} "
                f"spec_option={self.spec_option!r}>"
            )

    return ComplexArgumentType(subcommand, type_name, option_name, spec_option)<|return|>

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if extra_vars is None:
            return vars_dict
        if not isinstance(extra_vars, list):
            raise TypeError("extra_vars must be a list of dictionaries")
        for idx, item in enumerate(extra_vars):
            if not isinstance(item, dict):
                raise TypeError(f"Item at index {idx} in extra_vars is not a dictionary")
            vars_dict.update(item)
        return vars_dict<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Optional explicit type mapping per parser
    type_map = getattr(self, 'arg_type_map', {})
    parser_map = type_map.get(parser_name, {})

    for key, val in list(values_dict.items()):
        # Skip if value is already not a string
        if not isinstance(val, str):
            continue

        # Use explicit mapping if available
        if key in parser_map:
            target_type = parser_map[key]
            try:
                if target_type is bool:
                    values_dict[key] = val.lower() in ('true', '1', 'yes', 'on')
                else:
                    values_dict[key] = target_type(val)
                continue
            except Exception:
                # fall back to generic conversion
                pass

        # Generic conversion logic
        lowered = val.lower()
        if lowered in ('true', 'false'):
            values_dict[key] = lowered == 'true'
        elif val.isdigit() or (val.startswith('-') and val[1:].isdigit()):
            values_dict[key] = int(val)
        else:
            # Try float
            try:
                values_dict[key] = float(val)
                continue
            except ValueError:
                pass

            # Try comma‑separated list
            if ',' in val:
                parts = [p.strip() for p in val.split(',')]
                converted = []
                for p in parts:
                    lp = p.lower()
                    if lp in ('true', 'false'):
                        converted.append(lp == 'true')
                    elif p.isdigit() or (p.startswith('-') and p[1:].isdigit()):
                        converted.append(int(p))
                    else:
                        try:
                            converted.append(float(p))
                        except ValueError:
                            converted.append(p)
                values_dict[key] = converted
            # otherwise keep original string
    # values_dict is modified in place; no return value needed.<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    if not os.path.isdir(plugin_dir):
        raise ValueError(f"plugin_dir '{plugin_dir}' is not a directory")

    # Look for common spec file names
    spec_path = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break
    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'")

    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.endswith(".json"):
                data = json.load(f)
            else:
                if yaml is None:
                    raise ImportError("PyYAML is required to parse YAML plugin spec")
                data = yaml.safe_load(f)
    except Exception as exc:
        raise ValueError(f"Failed to parse plugin spec: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("Plugin spec root must be a dictionary")

    def _flatten(d, parent_key=""):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            elif isinstance(v, list):
                # Convert list to comma‑separated string
                flat[new_key] = ",".join(map(str, v))
            else:
                flat[new_key] = v
        return flat

    return _flatten(data)<|return|>

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    if env_var not in os.environ:
        config_path = getattr(self, 'config_path', None)
        if not config_path:
            raise ValueError('config_path attribute is missing or empty')
        os.environ[env_var] = str(config_path)<|return|>

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    norm_root = os.path.normpath(root)
    norm_path = os.path.normpath(path)
    # If root is empty, nothing to strip
    if not norm_root:
        raise ValueError("Root cannot be empty")
    # Ensure root ends with separator for comparison
    sep = os.sep
    # Handle case where root is the same as path
    if norm_path == norm_root:
        return ''
    # Ensure path starts with root followed by separator
    if norm_path.startswith(norm_root + sep):
        return norm_path[len(norm_root) + 1:]
    # On Windows, also consider case-insensitive comparison
    if os.name == 'nt':
        if norm_path.lower().startswith(norm_root.lower() + sep.lower()):
            return norm_path[len(norm_root) + 1:]
    raise ValueError(f"Path '{path}' does not start with root '{root}'")<|return|>
